import json
n=30
g=[[0]*n for _ in range(n)]
# Existing 25x25 frame at rows/cols 1..25.
for c in range(1,26):
    g[1][c]=g[25][c]=5
for r in range(1,26):
    g[r][1]=g[r][25]=5
# Add an inner 2 frame, then a 5 frame one cell further inward.
for c in range(2,25):
    g[2][c]=g[24][c]=2
for r in range(2,25):
    g[r][2]=g[r][24]=2
for c in range(3,24):
    g[3][c]=g[23][c]=5
for r in range(3,24):
    g[r][3]=g[r][23]=5
print(json.dumps(g,separators=(',',':')))
